return [{
  json: {
    triggerSource: 'manual',
    options: {
      dryRun: true,
      lookbackDays: 1,
      pageSize: 100,
      maxPages: 3,
      keyword: null
    }
  }
}];

return [{
  json: {
    triggerSource: 'schedule',
    options: {
      dryRun: false,
      lookbackDays: 1,
      pageSize: 100,
      maxPages: 3,
      keyword: null
    }
  }
}];

const input = $json ?? {};
let apiBaseUrlRaw = '';
let liveEnabled = false;
try {
  apiBaseUrlRaw = String($env.PAI_LOOP_API_BASE_URL ?? '').trim();
  liveEnabled = String($env.PAI_LOOP_LIVE_INGESTION_ENABLED ?? '').trim().toLowerCase() === 'true';
} catch {
  apiBaseUrlRaw = '';
  liveEnabled = false;
}
if (!apiBaseUrlRaw) {
  throw new Error('PAI_LOOP_API_BASE_URL is required for protected PPS ingestion');
}
let parsedBaseUrl;
try {
  parsedBaseUrl = new URL(apiBaseUrlRaw);
} catch {
  throw new Error('PAI_LOOP_API_BASE_URL must be an absolute HTTP(S) URL');
}
if (!['http:', 'https:'].includes(parsedBaseUrl.protocol) || parsedBaseUrl.username || parsedBaseUrl.password) {
  throw new Error('PAI_LOOP_API_BASE_URL must use HTTP(S) without embedded credentials');
}
const apiBaseUrl = parsedBaseUrl.toString().replace(/\/+$/, '');
const options = input.options ?? {};
const lookbackDays = Math.min(7, Math.max(1, Number(options.lookbackDays ?? 1)));
const pageSize = Math.min(100, Math.max(1, Math.trunc(Number(options.pageSize ?? 100))));
const maxPages = Math.min(10, Math.max(1, Math.trunc(Number(options.maxPages ?? 3))));
const to = new Date();
const from = new Date(to.getTime() - lookbackDays * 86400000);
const fromDate = from.toISOString().slice(0, 10);
const toDate = to.toISOString().slice(0, 10);
const keywordRaw = options.keyword == null ? '' : String(options.keyword).trim();
const keyword = keywordRaw ? keywordRaw.slice(0, 100) : null;
const dryRun = options.dryRun !== false || !liveEnabled;
const request = {
  from_date: fromDate,
  to_date: toDate,
  page_size: pageSize,
  max_pages: maxPages,
  dry_run: dryRun,
  ...(keyword ? { keyword } : {})
};
const keywordKey = keyword ? keyword.replace(/[^a-zA-Z0-9가-힣_-]/g, '_').slice(0, 32) : 'all';
return [{
  json: {
    runtime: {
      apiBaseUrl,
      triggerSource: input.triggerSource ?? 'unknown',
      liveEnabled,
      forcedDryRun: options.dryRun === false && !liveEnabled
    },
    idempotencyKey: `pps:${fromDate}:${toDate}:${keywordKey}:${dryRun ? 'dry' : 'live'}`,
    request
  }
}];

const response = $json?.body && typeof $json.body === 'object' ? $json.body : $json;
if (!response || typeof response !== 'object') {
  throw new Error('PPS ingestion response must be an object');
}
const requireString = (field) => {
  const value = response[field];
  if (typeof value !== 'string' || !value) throw new Error(`${field} must be a non-empty string`);
  return value;
};
const requireCount = (field) => {
  const value = response[field];
  if (!Number.isInteger(value) || value < 0) throw new Error(`${field} must be a non-negative integer`);
  return value;
};
const noticeKeys = response.notice_keys;
const warnings = response.warnings;
if (!Array.isArray(noticeKeys) || !noticeKeys.every((value) => typeof value === 'string')) {
  throw new Error('notice_keys must be a string array');
}
if (!Array.isArray(warnings) || !warnings.every((value) => typeof value === 'string')) {
  throw new Error('warnings must be a string array');
}
if (!response.window || typeof response.window.from !== 'string' || typeof response.window.to !== 'string') {
  throw new Error('window must contain string from/to fields');
}
if (typeof response.dry_run !== 'boolean') throw new Error('dry_run must be boolean');
const source = requireString('source');
const mode = requireString('mode');
const status = requireString('status');
if (source !== 'PPS') throw new Error('source must be PPS');
if (mode !== 'live') throw new Error('mode must be live');
if (status !== 'COMPLETED') throw new Error('status must be COMPLETED');
return [{
  json: {
    schemaVersion: '1.0',
    jobId: requireString('job_id'),
    status,
    source,
    mode,
    dryRun: response.dry_run,
    window: response.window,
    counts: {
      apiCalls: requireCount('api_calls'),
      fetched: requireCount('fetched'),
      matched: requireCount('matched'),
      created: requireCount('created'),
      updated: requireCount('updated'),
      duplicates: requireCount('duplicates'),
      quarantined: requireCount('quarantined')
    },
    noticeKeys,
    nextWatermark: requireString('next_watermark'),
    warnings,
    completedAt: new Date().toISOString()
  }
}];
